#!/usr/bin/env node
/**
 * Regenerates the data-driven parts of README.md from data/*.json.
 *
 * Everything between the DATA markers is generated by CI; hand-written prose
 * above/below is preserved. Charts are emitted as standalone SVG files under
 * docs/assets/ so GitHub renders them inline (no external service, no JS).
 *
 * Run: node scripts/build-readme.mjs
 */
import { readFileSync, readdirSync, mkdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dataDir = join(root, 'data');
const assetsDir = join(root, 'docs', 'assets');

const BEGIN = '<!-- DATA:BEGIN -->';
const END = '<!-- DATA:END -->';

const series = readdirSync(dataDir)
  .filter((f) => /^\d{4}-\d{2}-\d{2}\.json$/.test(f))
  .sort()
  .map((f) => {
    const d = JSON.parse(readFileSync(join(dataDir, f), 'utf8'));
    return { date: d.date, fii: Number(d?.equity?.fii_net ?? 0), dii: Number(d?.equity?.dii_net ?? 0) };
  });

if (!series.length) {
  console.error('no dated data files');
  process.exit(1);
}

const latest = series.at(-1);
const win = series.slice(-30);
const sum = (a, k) => a.reduce((x, y) => x + y[k], 0);
const crore = (n) => `${n >= 0 ? '+' : '\u2212'}${Math.abs(n).toLocaleString('en-IN', { maximumFractionDigits: 0 })}`;
const short = (n) => {
  const a = Math.abs(n);
  return `${n > 0 ? '+' : n < 0 ? '\u2212' : ''}${a >= 1000 ? `${(a / 1000).toFixed(a >= 10000 ? 0 : 1)}k` : a.toFixed(0)}`;
};
const mmdd = (s) => s.slice(5);

/* --- static SVG (fixed size, GitHub-friendly) --- */
function barsSvg(rows) {
  const w = 860, h = 280, pad = { t: 16, r: 12, b: 30, l: 70 };
  const iw = w - pad.l - pad.r, ih = h - pad.t - pad.b;
  const max = Math.max(1, ...rows.flatMap((r) => [Math.abs(r.fii), Math.abs(r.dii)]));
  const scale = ih / 2 / max, zero = pad.t + ih / 2, slot = iw / rows.length;
  const bw = Math.max(2, Math.min(10, slot / 2.6));
  const bars = rows.map((r, i) => {
    const x = pad.l + i * slot + (slot - bw * 2 - 1) / 2;
    const fh = Math.abs(r.fii) * scale, dh = Math.abs(r.dii) * scale;
    return `<g><title>${r.date}: FII ${crore(r.fii)}, DII ${crore(r.dii)}</title>
      <rect x="${x.toFixed(1)}" y="${(r.fii >= 0 ? zero - fh : zero).toFixed(1)}" width="${bw}" height="${fh.toFixed(1)}" rx="1.5" fill="#38bdf8"/>
      <rect x="${(x + bw + 1).toFixed(1)}" y="${(r.dii >= 0 ? zero - dh : zero).toFixed(1)}" width="${bw}" height="${dh.toFixed(1)}" rx="1.5" fill="#fbbf24"/></g>`;
  }).join('');
  const ticks = [-max, 0, max].map((v) => {
    const y = zero - v * scale;
    return `<line x1="${pad.l}" x2="${w - pad.r}" y1="${y.toFixed(1)}" y2="${y.toFixed(1)}" stroke="#3b4f70" stroke-dasharray="3 4"/>
      <text x="${pad.l - 8}" y="${(y + 4).toFixed(1)}" fill="#7d92b0" font-size="11" font-family="monospace" text-anchor="end">${short(v)}</text>`;
  }).join('');
  const labels = rows.map((r, i) => (i % Math.ceil(rows.length / 6) && i !== rows.length - 1 ? '' :
    `<text x="${(pad.l + i * slot + slot / 2).toFixed(1)}" y="${h - 8}" fill="#7d92b0" font-size="11" font-family="monospace" text-anchor="middle">${mmdd(r.date)}</text>`)).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"><rect width="${w}" height="${h}" fill="#0b1220"/>${ticks}${bars}${labels}</svg>`;
}

function cumSvg(rows) {
  const w = 860, h = 240, pad = { t: 18, r: 12, b: 26, l: 70 };
  const iw = w - pad.l - pad.r, ih = h - pad.t - pad.b;
  let cf = 0, cd = 0;
  const pts = rows.map((r, i) => { cf += r.fii; cd += r.dii; return { x: pad.l + (i * iw) / Math.max(1, rows.length - 1), f: cf, d: cd }; });
  const vals = pts.flatMap((p) => [p.f, p.d, 0]);
  const lo0 = Math.min(...vals), hi0 = Math.max(...vals), gap = Math.max(1, hi0 - lo0) * 0.08;
  const lo = lo0 - gap, hi = hi0 + gap, span = hi - lo;
  const y = (v) => pad.t + ih - ((v - lo) / span) * ih;
  const path = (k) => pts.map((p, i) => `${i ? 'L' : 'M'}${p.x.toFixed(1)},${y(p[k]).toFixed(1)}`).join(' ');
  const ticks = [lo, lo + span / 2, hi].map((v) =>
    `<line x1="${pad.l}" x2="${w - pad.r}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}" stroke="#3b4f70" stroke-dasharray="3 4"/>
     <text x="${pad.l - 8}" y="${(y(v) + 4).toFixed(1)}" fill="#7d92b0" font-size="11" font-family="monospace" text-anchor="end">${short(v)}</text>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"><rect width="${w}" height="${h}" fill="#0b1220"/>${ticks}
    <path d="${path('f')}" fill="none" stroke="#38bdf8" stroke-width="2.2"/>
    <path d="${path('d')}" fill="none" stroke="#fbbf24" stroke-width="2.2"/>
    <text x="${pad.l}" y="${h - 6}" fill="#7d92b0" font-size="11" font-family="monospace">${rows[0].date}</text>
    <text x="${w - pad.r}" y="${h - 6}" fill="#7d92b0" font-size="11" font-family="monospace" text-anchor="end">${rows.at(-1).date}</text></svg>`;
}

mkdirSync(assetsDir, { recursive: true });
writeFileSync(join(assetsDir, 'daily-flows.svg'), barsSvg(win));
writeFileSync(join(assetsDir, 'cumulative-flows.svg'), cumSvg(series));

const rows12 = series.slice(-12).reverse();
const table = [
  '| Date | FII net (₹ cr) | DII net (₹ cr) | Combined |',
  '| :--- | ---: | ---: | ---: |',
  ...rows12.map((r) => `| ${r.date} | ${crore(r.fii)} | ${crore(r.dii)} | ${crore(r.fii + r.dii)} |`),
].join('\n');

const block = `${BEGIN}
## Latest reading

**${latest.date}** — FII ${crore(latest.fii)} cr · DII ${crore(latest.dii)} cr · combined ${crore(latest.fii + latest.dii)} cr

| Metric | Value |
| :--- | ---: |
| Sessions archived | ${series.length} |
| FII cumulative (${win.length}d) | ${crore(sum(win, 'fii'))} cr |
| DII cumulative (${win.length}d) | ${crore(sum(win, 'dii'))} cr |
| Latest session | ${latest.date} |

![FII vs DII daily net flows](docs/assets/daily-flows.svg)

![Cumulative institutional flow](docs/assets/cumulative-flows.svg)

## Recent sessions

${table}

## Live URLs

| Host | URL | Role |
| :--- | :--- | :--- |
| GitHub Pages | https://chirag127.github.io/fii-dii-activity-api/ | canonical (domain-independent) |
| Alias (optional) | https://gh.oriz.in/fii-dii-activity-api/ | alias host, depends on the custom domain |

## API

| Endpoint | Payload |
| :--- | :--- |
| \`api/v1/data.json\` | every session |
| \`api/v1/index.json\` | date index |
| \`data/latest.json\` | latest session only |
| \`data/<YYYY-MM-DD>.json\` | one session |

${END}`;

const readmePath = join(root, 'README.md');
let readme = existsSync(readmePath) ? readFileSync(readmePath, 'utf8') : '# FII/DII Activity API\n';
const start = readme.indexOf(BEGIN);
const end = readme.indexOf(END);
if (start !== -1 && end !== -1) {
  readme = readme.slice(0, start) + block + readme.slice(end + END.length);
} else {
  readme = `${readme.trimEnd()}\n\n${block}\n`;
}
writeFileSync(readmePath, readme);

console.log(`README updated: ${series.length} sessions, ${rows12.length} rows, charts in docs/assets/`);
